    "pp.help.q1": "How does Flouna pick the best option?",
    "pp.help.a1":
      "We compare the final effective price (item + delivery − offers), delivery or pickup time, and ratings across platforms, then recommend the single best choice, with alternatives if you'd rather optimise for speed.",
    "pp.help.q2": "Where do my orders actually get placed?",
    "pp.help.a2":
      "Right inside Flouna. You order and pay here, and we route it to the restaurant or mobility partner fulfilling it.",
    "pp.help.q3": "How do refunds work?",
    "pp.help.a3":
      "Payments are processed securely via Cashfree. Refunds for cancelled orders return to your original payment method within 5 to 7 business days.",
    "pp.help.q4": "Is my data safe?",
    "pp.help.a4":
      "Yes. Your password is stored hashed, sessions use secure cookies, and we never sell your personal data.",
