    "pp.rew.step3": "ಆಫರ್ ಕೋಡ್ ಪ್ರತ್ಯೇಕವಾಗಿ ಅನ್ವಯವಾಗುತ್ತದೆ",
    "pp.rew.step3Body": "ಆಫರ್ ಪಟ್ಟಿಯಿಂದ ಕೋಡ್ ಅನ್ವಯಿಸಿದರೆ ಅದು ಮುಂದಿನ ಚೆಕ್‌ಔಟ್‌ಗೆ ಉಳಿಯುತ್ತದೆ, ಅಲ್ಲಿ ರಿಯಾಯಿತಿ ಸರ್ವರ್‌ನಲ್ಲಿ ಹೊಸದಾಗಿ ಲೆಕ್ಕವಾಗುತ್ತದೆ. ಕೋಡ್ ಮತ್ತು ಕ್ಯಾಶ್‌ಬ್ಯಾಕ್ ಪರಸ್ಪರ ಸ್ವತಂತ್ರ.",
