    "pp.rew.step4Body": "ನಿಮ್ಮ ಬಾಕಿ ಬಹುಮಾನ ಇತಿಹಾಸದ ನಮೂದುಗಳ ಮೊತ್ತ, ಪ್ರತ್ಯೇಕ ಸಂಖ್ಯೆ ಅಲ್ಲ. ಒಂದು ಸಾಲು ತಪ್ಪೆನಿಸಿದರೆ ಅದನ್ನು ಸೃಷ್ಟಿಸಿದ ಆರ್ಡರ್‌ವರೆಗೆ ಪತ್ತೆ ಮಾಡಬಹುದು.",
