    "dt.intro": "ನಿಮ್ಮ ಬಗ್ಗೆ ನಮ್ಮ ಬಳಿ ಏನಿದೆ, ಮತ್ತು ಅದರೊಂದಿಗೆ ನೀವು ನಮ್ಮಿಂದ ಏನು ಮಾಡಿಸಬಹುದು. ಇವು ನಮ್ಮ ಗೌಪ್ಯತಾ ನೀತಿ ಮತ್ತು ಡಿಜಿಟಲ್ ವೈಯಕ್ತಿಕ ಡೇಟಾ ಸಂರಕ್ಷಣಾ ಕಾಯ್ದೆಯ ಅಡಿಯಲ್ಲಿ ನಿಮ್ಮ ಹಕ್ಕುಗಳು, ಉಪಕಾರಗಳಲ್ಲ.",
