    "dt.improving": "ನಮ್ಮ ಶಿಫಾರಸುಗಳನ್ನು ಸುಧಾರಿಸುವುದು",
    "dt.exclude": "ನನ್ನ ಡೇಟಾವನ್ನು ತರಬೇತಿಯಿಂದ ಹೊರಗಿಡಿ",
