    "pp.rew.howTitle": "இது எப்படி வேலை செய்கிறது",
    "pp.rew.step1": "வழக்கம் போல் ஆர்டர் செய்யுங்கள்",
    "pp.rew.step1Body": "நீங்கள் Flouna வழியாக ஆர்டர் செய்யும்போது எங்களுக்கு சிறிய மார்ஜின் கிடைக்கிறது. அதன் ஒரு பங்கு எங்களிடம் இல்லாமல் உங்களுக்குத் திரும்புகிறது.",
    "pp.rew.step2": "ஆர்டர் முடிந்ததும் கேஷ்பேக் வரும்",
    "pp.rew.step2Body": "பணம் செலுத்தும்போது அல்ல, ஆர்டர் செய்யும்போதும் அல்ல. ஆர்டர் முடிந்ததும் தொகை தானாகச் சேரும், ஒரு ஆர்டருக்கு ஒருமுறை.",
    "pp.rew.step3": "சலுகைக் குறியீடுகள் தனியாகச் சேரும்",
    "pp.rew.step3Body": "சலுகைப் பட்டியலிலிருந்து குறியீட்டைப் பயன்படுத்தினால் அது அடுத்த செக்அவுட்டுக்குச் சேமிக்கப்படும், அங்கு தள்ளுபடி சர்வரில் புதிதாகக் கணக்கிடப்படும். குறியீடும் கேஷ்பேக்கும் ஒன்றுக்கொன்று சார்பற்றவை.",
    "pp.rew.step4": "ஒவ்வொரு ரூபாயையும் கண்டறியலாம்",
    "pp.rew.step4Body": "உங்கள் இருப்பு வெகுமதி வரலாற்றின் பதிவுகளின் கூட்டுத்தொகை, தனியாக வைக்கப்பட்ட எண் அல்ல. ஒரு வரி தவறாகத் தோன்றினால், அதை உருவாக்கிய ஆர்டர் வரை கண்டறியலாம்.",
    "pp.rew.ratesNote": "கேஷ்பேக் விகிதங்களை Flouna நிர்ணயிக்கிறது, அவை மாறலாம். ஏற்கனவே வரவு வைக்கப்பட்டது உங்களுடையதே.",
    "pp.rew.seeHistory": "உங்கள் வெகுமதி வரலாற்றைப் பாருங்கள்",
