    "adv.m.foodLiveDinner": "சரியான நேரம், இரவு உணவு ஆஃபர் இப்போது நடப்பில் உள்ளது. விலைகள் மிகச் சிறப்பாக உள்ளன.",
    "adv.m.foodSoonLunch": "சுமார் {wait} இல் மதிய உணவு டீலுடன் ₹{rupees} நேரடி தள்ளுபடி எதிர்பார்க்கப்படுகிறது. இப்போதே ஆர்டர் செய்யவா, அல்லது காத்திருந்து சேமிக்கவா?",
    "adv.m.foodSoonSnack": "சுமார் {wait} இல் மாலை சிற்றுண்டி ஆஃபருடன் ₹{rupees} நேரடி தள்ளுபடி எதிர்பார்க்கப்படுகிறது. இப்போதே ஆர்டர் செய்யவா, அல்லது காத்திருந்து சேமிக்கவா?",
    "adv.m.foodSoonDinner": "சுமார் {wait} இல் இரவு உணவு ஆஃபருடன் ₹{rupees} நேரடி தள்ளுபடி எதிர்பார்க்கப்படுகிறது. இப்போதே ஆர்டர் செய்யவா, அல்லது காத்திருந்து சேமிக்கவா?",
    "adv.m.foodNone": "விரைவில் இதைவிடச் சிறந்த ஆஃபர் எதுவும் இல்லை, இப்போது ஆர்டர் செய்வது நல்லது.",
    "adv.m.rideEasing": "சுமார் {wait} இல் பீக் நேரக் கட்டணம் குறையத் தொடங்கும், கட்டணம் சுமார் ₹{rupees} குறையலாம்.",
    "adv.m.ridePeak": "இது அலுவலகப் பயண நெரிசல் நேரம், எல்லா இடங்களிலும் கட்டணம் அதிகம், சிறிது நேரம் காத்திருந்தாலும் பயனில்லை. இப்போதே புக் செய்வது சரி.",
    "adv.m.rideOffPeak": "இப்போது நெரிசல் இல்லாத நேரம், கட்டணம் மிகக் குறைவு. புக் செய்ய நல்ல நேரம்.",
    "adv.m.historyWaitFood": "சமீபத்திய விலைகளின்படி, இது வழக்கமாக {wait} கழித்து சுமார் ₹{rupees} மலிவாக இருக்கும். இப்போதே ஆர்டர் செய்யவா, அல்லது காத்திருந்து சேமிக்கவா?",
    "adv.m.historyWaitRide": "சமீபத்திய கட்டணங்களின்படி, இது வழக்கமாக {wait} கழித்து சுமார் ₹{rupees} மலிவாக இருக்கும். இப்போதே புக் செய்யவா, அல்லது காத்திருந்து சேமிக்கவா?",
    "adv.m.historyNow": "சமீபத்திய விலைகளின்படி, இப்போதே கிட்டத்தட்ட சிறந்த நேரம், காத்திருந்தால் இதைவிட நல்ல டீல் கிடைப்பது அரிது.",
    "adv.m.foodHeavyRain": "கனமழை பெய்கிறது, டெலிவரி சற்று தாமதமாகலாம், ஆனால் வீட்டுக்கே ஆர்டர் செய்தால் நனையாமல் இருப்பீர்கள்.",
    "adv.m.foodRain": "மழை பெய்யும் போல் உள்ளது, வெளியே செல்வதைவிட வீட்டுக்கு ஆர்டர் செய்வது நல்லது.",
    "adv.m.rideHeavyRain": "கனமழை, பயணங்களுக்குத் தேவை அதிகம், கட்டணம் உயர்ந்து வருகிறது. பயணம் அவசியமென்றால் சீக்கிரம் புக் செய்யுங்கள்.",
    "adv.m.rideRain": "மழை எதிர்பார்க்கப்படுகிறது, கட்டணம் உயரும், கேப்கள் கிடைப்பது கடினம். சீக்கிரம் புக் செய்வது பாதுகாப்பானது.",
